  const date=value=>validDate(value)?value.replace(/-/g,'.'):'날짜 확인 필요',short=value=>validDate(value)?value.slice(5).replace('-','.'):'',offset=(value,days)=>new Date(Date.parse(value+'T00:00:00Z')+days*86400000).toISOString().slice(0,10);
